#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn split_and_append(list: &Vec<i32>, n: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        0 < n,
        n < list.len(),
    ensures
        new_list.len() == list.len(),
        // Left-rotate by n: result is list[n..] followed by list[..n]
        new_list@ == list@.subrange(n as int, list.len() as int)
                        + list@.subrange(0, n as int),
{
    let len = list.len();
    let mut out: Vec<i32> = Vec::with_capacity(len);

    // First append list[n..len)
    let mut i: usize = n;
    while i < len
        invariant
            len == list.len(),
            0 < n,
            n < len,
            n <= i,
            i <= len,
            out.len() == i - n,
            out@ == list@.subrange(n as int, i as int),
        decreases len - i
    {
        out.push(list[i]);
        i += 1;
    }

    // Then append list[0..n)
    let mut j: usize = 0;
    while j < n
        invariant
            len == list.len(),
            0 < n,
            n < len,
            j <= n,
            out.len() == (len - n) + j,
            out@ == list@.subrange(n as int, len as int)
                    + list@.subrange(0, j as int),
        decreases n - j
    {
        out.push(list[j]);
        j += 1;
    }

    out
}

} // verus!